<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model;
class QualityImprovementPlan extends Model { protected $fillable=['academic_year','source','reference','quality_kpi_id','quality_survey_id','observation','root_cause','improvement_action','desired_outcome','responsible','owner_user_id','start_date','due_date','priority','progress_percent','status','closed_date','closure_evidence','verification_result','data_source','created_by','verified_by','verified_at']; protected $casts=['start_date'=>'date','due_date'=>'date','closed_date'=>'date','verified_at'=>'datetime','progress_percent'=>'integer']; public function owner(){return $this->belongsTo(User::class,'owner_user_id');} public function creator(){return $this->belongsTo(User::class,'created_by');} public function verifier(){return $this->belongsTo(User::class,'verified_by');} public function kpi(){return $this->belongsTo(QualityKpi::class,'quality_kpi_id');} public function survey(){return $this->belongsTo(QualitySurvey::class,'quality_survey_id');} }
